effect.shader:
// globais do Node ligados ao motor (tools/nodevideo/ligar_globais.py)
#define _viewport_ratio acProporcaoDoNode
vec2 u_xlat0;
bvec2 u_xlatb0;
vec4 u_xlat1;
bool u_xlatb1;
vec4 u_xlat2;
vec4 u_xlat3;
vec4 u_xlat4;
vec4 u_xlat5;
vec3 u_xlat6;
float u_xlat8;
bool u_xlatb8;
float u_xlat12;
float u_xlat13;
float u_xlat18;
float u_xlat19;
bool u_xlatb19;
void main()
{
    u_xlat0.xy = vec2(_viewport_ratio.x, _viewport_ratio.y) * _pointA.xy;
    u_xlat1.xy = vec2(_pointB.x, _pointB.y) * vec2(_viewport_ratio.x, _viewport_ratio.y) + (-u_xlat0.xy);
    u_xlat12 = u_xlat0.y * u_xlat1.x;
    u_xlat12 = u_xlat1.y * u_xlat0.x + (-u_xlat12);
    u_xlat1.zw = (-u_xlat1.yy);
    u_xlat18 = dot(u_xlat1.xz, u_xlat1.xw);
    u_xlat13 = sqrt(u_xlat18);
    u_xlat2.xy = acScreenNorm.xy * vec2(_viewport_ratio.x, _viewport_ratio.y);
    u_xlat19 = u_xlat1.x * u_xlat2.y;
    u_xlat19 = (-u_xlat1.y) * u_xlat2.x + u_xlat19;
    u_xlat12 = u_xlat12 + u_xlat19;
    u_xlat12 = u_xlat12 / u_xlat13;
    u_xlat0.xy = acScreenNorm.xy * vec2(_viewport_ratio.x, _viewport_ratio.y) + (-u_xlat0.xy);
    u_xlat0.x = dot(u_xlat1.xy, u_xlat0.xy);
    u_xlat6.x = dot(u_xlat1.xy, u_xlat1.xy);
    u_xlat0.x = u_xlat0.x / u_xlat6.x;
    if(int(_shape) == 0) {
        u_xlat13 = u_xlat0.x + -0.5;
        u_xlat13 = dot(vec2(u_xlat13), _scale.xxyx.yy);
        u_xlat13 = u_xlat13 * u_xlat13;
        u_xlat13 = u_xlat13 * -0.5;
        u_xlat13 = u_xlat13 / _scale.xxyx.z;
        u_xlat13 = u_xlat13 * 1.44269502;
        u_xlat13 = exp2(u_xlat13);
        u_xlat19 = _scale.xxyx.z * 6.28318548;
        u_xlat19 = sqrt(u_xlat19);
        u_xlat13 = u_xlat13 / u_xlat19;
        u_xlat19 = sqrt(u_xlat6.x);
        u_xlat13 = u_xlat19 * u_xlat13;
    } else {
        u_xlatb19 = int(_shape)==1;
        u_xlat0.x = u_xlat0.x + -0.5;
        u_xlat0.x = u_xlat0.x * _scale.xxyx.y;
        u_xlat2.x = (-u_xlat0.x) * u_xlat0.x + _scale.xxyx.z;
        u_xlatb8 = u_xlat2.x>=0.0;
        u_xlat2.x = sqrt(u_xlat2.x);
        u_xlat2.x = u_xlatb8 ? u_xlat2.x : float(0.0);
        u_xlat6.x = sqrt(u_xlat6.x);
        u_xlat2.x = u_xlat6.x * u_xlat2.x;
        u_xlat0.x = u_xlat0.x + u_xlat0.x;
        u_xlat8 = _scale.xxyx.y + _scale.xxyx.y;
        u_xlat0.x = u_xlat0.x / u_xlat8;
        u_xlat0.x = u_xlat0.x + 0.5;
        u_xlatb8 = u_xlat0.x<0.0;
        u_xlatb0.x = 1.0<u_xlat0.x;
        u_xlatb0.x = u_xlatb0.x || u_xlatb8;
        u_xlat0.x = (u_xlatb0.x) ? 0.0 : _scale.xxyx.z;
        u_xlat0.x = u_xlat6.x * u_xlat0.x;
        u_xlat13 = (u_xlatb19) ? u_xlat2.x : u_xlat0.x;
    }
    u_xlat2 = texture(inputImg, acScreenNorm.xy);
    u_xlat0.x = inversesqrt(u_xlat18);
    u_xlat6.xz = u_xlat1.yx * vec2(-1.0, 1.0);
    u_xlat0.xy = u_xlat0.xx * u_xlat6.xz;
    u_xlat0.xy = u_xlat0.xy / vec2(_viewport_ratio.x, _viewport_ratio.y);
    u_xlat18 = u_xlat13 * _split;
    u_xlatb1 = 0.0<u_xlat12;
    if(u_xlatb1){
        u_xlatb1 = u_xlat18<u_xlat12;
        if(u_xlatb1){
            u_xlat1.xy = vec2(u_xlat18) * u_xlat0.xy;
            u_xlat19 = (-u_xlat13) * _split + u_xlat12;
            u_xlat19 = (-u_xlat19) * _fix_edge;
            u_xlat19 = u_xlat19 * 14.4269505;
            u_xlat19 = exp2(u_xlat19);
            u_xlat1.xy = (-u_xlat1.xy) * vec2(u_xlat19) + acScreenNorm.xy;
            u_xlat3 = texture(inputImg, u_xlat1.xy);
        } else {
            u_xlat3.x = float(0.0);
            u_xlat3.y = float(0.0);
            u_xlat3.z = float(0.0);
            u_xlat3.w = float(0.0);
        }
    } else {
        u_xlatb1 = 0<int(_bidirection);
        if(u_xlatb1){
            u_xlatb1 = u_xlat18<(-u_xlat12);
            if(u_xlatb1){
                u_xlat0.xy = vec2(u_xlat18) * u_xlat0.xy;
                u_xlat12 = (-u_xlat13) * _split + (-u_xlat12);
                u_xlat12 = (-u_xlat12) * _fix_edge;
                u_xlat12 = u_xlat12 * 14.4269505;
                u_xlat12 = exp2(u_xlat12);
                u_xlat0.xy = u_xlat0.xy * vec2(u_xlat12) + acScreenNorm.xy;
                u_xlat3 = texture(inputImg, u_xlat0.xy);
            } else {
                u_xlat3.x = float(0.0);
                u_xlat3.y = float(0.0);
                u_xlat3.z = float(0.0);
                u_xlat3.w = float(0.0);
            }
        } else {
            u_xlat3 = u_xlat2;
        }
    }
    if(int(_use_inner_mask) != 0) {
        u_xlatb0.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_show_inner_mask)), ivec4(1, 1, 0, 0)).xy;
        u_xlat1 = (u_xlatb0.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat3;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat2 = u_xlat2 * u_xlat5;
        u_xlat1 = u_xlat1 * u_xlat4 + u_xlat2;
        u_xlat0.x = u_xlat4.x * u_xlat1.w;
        fragColor.w = (u_xlatb0.y) ? u_xlat0.x : u_xlat1.w;
        fragColor.xyz = u_xlat1.xyz;
    } else {
        fragColor = u_xlat3;
    }
    return;
}
